  : report_text;

const matrix_html = markdownToSimpleHtml(matrix_text);
const report_html = markdownToSimpleHtml(report_text);

const email_html = `
<html>
<body style="font-family:Arial,sans-serif;max-width:900px;margin:0 auto;padding:24px;color:#222;line-height:1.6">
  <h1 style="color:#1a1a2e;margin-bottom:4px;">📊 Aktien-Tagesreport</h1>
  <p style="color:#666;margin-top:0;">
    ${new Date().toLocaleDateString('de-DE', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })}
  </p>

  <div style="background:#f8f9fa;padding:22px;border-radius:10px;border:1px solid #e5e5e5;font-size:15px;">
    ${report_html}
  </div>

  <hr style="margin-top:28px;border:none;border-top:1px solid #ddd;">
  <p style="color:#999;font-size:12px;">
    Automatisch generiert. Keine Anlageberatung, nur automatisierte Markt- und Aktienbeobachtung.
  </p>
</body>
</html>`;

return [
  {
    json: {
      report_text,
      matrix_text,
      matrix_html,
      email_html,
      zeitstempel: new Date().toISOString()
    }
  }
];

const j = $json;
const warns = [
  ...(j.missing_warnings || []),
  ...(j.required_corrections || []).map(c => 'Pruef-Agent-Korrektur: ' + c)
];
if (warns.length === 0) warns.push('Pruef-Agent hat den Bericht abgelehnt (quality_score ' + j.quality_score + '), keine Details verfuegbar.');

const body = '⚠️ Tagesreport NICHT versendet (run_id ' + j.run_id + ', quality_score ' + j.quality_score + ')\n\n• ' + warns.join('\n• ');
const formatted_body = '<b>⚠️ Tagesreport NICHT versendet</b> (run_id ' + j.run_id + ', quality_score ' + j.quality_score + ')<br><ul>' + warns.map(w => '<li>' + w + '</li>').join('') + '</ul>';

return [{ json: { ...j, _warn_body: body, _warn_formatted_body: formatted_body } }];

// Prioritaet 6: einheitliches Envelope. Pro Lauf feuert genau einer der
// drei Zweige (Versand echt / DRY_RUN uebersprungen / Ablehnung) -- der
// Versand-Zweig kann dabei bis zu 2 Items liefern (Matrix + E-Mail).
const items = $input.all().map(i => i.json);

let runId = null, startedAt = null, qualityScore = null;
try {
  const eing = $('Eingabe normalisieren').all()[0].json;
  runId = eing.run_id;
  startedAt = eing._run_started_at || null;
  qualityScore = eing.quality_score;
} catch (e) {}

const zweig = items.length > 0 ? items[0]._zweig : null;

let processed, successful, failed, warnings, errors, status;

if (zweig === 'dry_run') {
  processed = 1; successful = 0; failed = 0; warnings = []; errors = []; status = 'skipped';
} else if (zweig === 'abgelehnt') {
  processed = 1;
  const sendFailed = items[0]._send_failed === true;
  successful = 0;
  failed = 1;
  warnings = [];
  errors = [{ node: 'IF: Freigegeben?', message: 'Pruef-Agent hat den Bericht abgelehnt (quality_score ' + qualityScore + ')' }];
  if (sendFailed) errors.push({ node: 'Matrix: Fehler-Alert', message: items[0]._send_error || 'Unbekannter Fehler' });
  status = 'failed';
} else if (zweig === 'versand') {
  processed = items.length;
  const failedItems = items.filter(i => i._send_failed === true);
  failed = failedItems.length;
  successful = processed - failed;
  warnings = [];
  errors = failedItems.map(i => ({ node: i._kanal === 'matrix' ? 'Matrix: Tagesreport senden' : 'E-Mail Report senden', message: i._send_error || 'Unbekannter Fehler' }));
  status = failed === 0 ? 'success' : (successful === 0 ? 'failed' : 'partial_failure');
} else {
  processed = 0; successful = 0; failed = 0; warnings = [];
  errors = [{ node: 'Abschluss-Ergebnis bauen', message: 'Kein bekannter Zweig erkannt (unerwarteter Workflow-Pfad, ' + items.length + ' Items ohne _zweig-Feld)' }];
  status = 'failed';
}

return [{ json: {
  ok: failed === 0,
  workflow: '05 \u2013 Tagesreport',
  run_id: runId,
  processed,
  successful,
  failed,
  warnings,
  errors,
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  status
} }];

