// drei Zweige (Versand echt / DRY_RUN uebersprungen / Ablehnung) -- der
// Versand-Zweig kann dabei bis zu 2 Items liefern (Matrix + E-Mail).
const items = $input.all().map(i => i.json);

let runId = null, startedAt = null, qualityScore = null;
try {
  const eing = $('Eingabe normalisieren').all()[0].json;
  runId = eing.run_id;
  startedAt = eing._run_started_at || null;
  qualityScore = eing.quality_score;
} catch (e) {}

const zweig = items.length > 0 ? items[0]._zweig : null;

let processed, successful, failed, warnings, errors, status;

if (zweig === 'dry_run') {
  processed = 1; successful = 0; failed = 0; warnings = []; errors = []; status = 'skipped';
} else if (zweig === 'abgelehnt') {
  processed = 1;
  const sendFailed = items[0]._send_failed === true;
  successful = 0;
  failed = 1;
  warnings = [];
  errors = [{ node: 'IF: Freigegeben?', message: 'Pruef-Agent hat den Bericht abgelehnt (quality_score ' + qualityScore + ')' }];
  if (sendFailed) errors.push({ node: 'Matrix: Fehler-Alert', message: items[0]._send_error || 'Unbekannter Fehler' });
  status = 'failed';
} else if (zweig === 'versand') {
  processed = items.length;
  const failedItems = items.filter(i => i._send_failed === true);
  failed = failedItems.length;
  successful = processed - failed;
  warnings = [];
  errors = failedItems.map(i => ({ node: i._kanal === 'matrix' ? 'Matrix: Tagesreport senden' : 'E-Mail Report senden', message: i._send_error || 'Unbekannter Fehler' }));
  status = failed === 0 ? 'success' : (successful === 0 ? 'failed' : 'partial_failure');
} else {
  processed = 0; successful = 0; failed = 0; warnings = [];
  errors = [{ node: 'Abschluss-Ergebnis bauen', message: 'Kein bekannter Zweig erkannt (unerwarteter Workflow-Pfad, ' + items.length + ' Items ohne _zweig-Feld)' }];
  status = 'failed';
}

return [{ json: {
  ok: failed === 0,
  workflow: '05 \u2013 Tagesreport',
  run_id: runId,
  processed,
  successful,
  failed,
  warnings,
  errors,
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  status
} }];
